type Scalar = string | number | boolean | bigint | null | undefined;

type Node =
  | { type: "text"; value: string }
  | { type: "interpolation"; path: string; escaped: boolean; location: Location }
  | { type: "if"; path: string; body: Node[]; alternate: Node[]; location: Location }
  | { type: "each"; path: string; body: Node[]; alternate: Node[]; location: Location };

interface Location {
  line: number;
  column: number;
}

interface Block {
  kind: "if" | "each";
  node: Extract<Node, { type: "if" | "each" }>;
  parent: Node[];
  inAlternate: boolean;
}

interface Context {
  root: unknown;
  current: unknown;
  index?: number;
}

const escapeHtml = (value: string): string =>
  value.replace(/[&<>"']/g, (character) =>
    ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[character]!,
  );

function locationAt(template: string, offset: number): Location {
  const before = template.slice(0, offset);
  const lastNewline = before.lastIndexOf("\n");
  return { line: (before.match(/\n/g) ?? []).length + 1, column: offset - lastNewline };
}

function syntaxError(template: string, offset: number, message: string): Error {
  const { line, column } = locationAt(template, offset);
  return new Error(`${message} at line ${line}, column ${column}`);
}

function parse(template: string): Node[] {
  const root: Node[] = [];
  let target = root;
  const blocks: Block[] = [];
  let cursor = 0;

  while (cursor < template.length) {
    const start = template.indexOf("{{", cursor);
    if (start === -1) {
      if (cursor < template.length) target.push({ type: "text", value: template.slice(cursor) });
      break;
    }
    if (start > cursor) target.push({ type: "text", value: template.slice(cursor, start) });

    const triple = template.startsWith("{{{", start);
    const closing = triple ? "}}}" : "}}";
    const contentStart = start + (triple ? 3 : 2);
    const end = template.indexOf(closing, contentStart);
    if (end === -1) throw syntaxError(template, start, "Unclosed tag");

    const raw = template.slice(contentStart, end);
    const token = raw.trim();
    const location = locationAt(template, start);
    cursor = end + closing.length;

    if (!token) throw syntaxError(template, start, "Empty tag");
    if (triple) {
      if (token.startsWith("#") || token === "else" || token.startsWith("/") || token.startsWith("!")) {
        throw syntaxError(template, start, "Triple braces may only interpolate a value");
      }
      target.push({ type: "interpolation", path: token, escaped: false, location });
      continue;
    }
    if (token.startsWith("!")) continue;

    if (token.startsWith("#")) {
      const match = /^#(if|each)\s+(.+)$/.exec(token);
      if (!match) throw syntaxError(template, start, "Unknown or malformed block");
      const [, kind, path] = match;
      const node = { type: kind as "if" | "each", path: path.trim(), body: [], alternate: [], location };
      target.push(node);
      blocks.push({ kind: node.type, node, parent: target, inAlternate: false });
      target = node.body;
      continue;
    }
    if (token === "else") {
      const block = blocks.at(-1);
      if (!block) throw syntaxError(template, start, "else outside a block");
      if (block.inAlternate) throw syntaxError(template, start, "Duplicate else");
      block.inAlternate = true;
      target = block.node.alternate;
      continue;
    }
    if (token.startsWith("/")) {
      const kind = token.slice(1).trim();
      const block = blocks.at(-1);
      if (!block) throw syntaxError(template, start, `Closing ${kind || "block"} without an open block`);
      if (kind !== block.kind) {
        throw syntaxError(template, start, `Mismatched close: expected /${block.kind}, got /${kind || "?"}`);
      }
      blocks.pop();
      target = block.parent;
      continue;
    }
    target.push({ type: "interpolation", path: token, escaped: true, location });
  }

  const open = blocks.at(-1);
  if (open) throw new Error(`Unclosed ${open.kind} block at line ${open.node.location.line}, column ${open.node.location.column}`);
  return root;
}

function resolve(path: string, context: Context): unknown {
  if (path === "this") return context.current;
  if (path === "@index") return context.index;
  if (!/^[A-Za-z_$][\w$]*(?:\.[A-Za-z_$][\w$]*)*$/.test(path)) return undefined;

  let value: unknown = context.root;
  for (const part of path.split(".")) {
    if (value === null || value === undefined) return undefined;
    if (typeof value !== "object" && typeof value !== "function") return undefined;
    value = (value as Record<string, unknown>)[part];
  }
  return value;
}

function isTruthy(value: unknown): boolean {
  return !(value === false || value === null || value === undefined || value === 0 || value === "" || (Array.isArray(value) && value.length === 0));
}

function scalarText(value: unknown, location: Location): string {
  if (value === null || value === undefined) return "";
  if (typeof value === "string" || typeof value === "number" || typeof value === "boolean" || typeof value === "bigint") return String(value);
  throw new Error(`Cannot render ${typeof value} as text at line ${location.line}, column ${location.column}`);
}

function renderNodes(nodes: Node[], context: Context): string {
  let output = "";
  for (const node of nodes) {
    if (node.type === "text") output += node.value;
    else if (node.type === "interpolation") {
      const text = scalarText(resolve(node.path, context), node.location);
      output += node.escaped ? escapeHtml(text) : text;
    } else if (node.type === "if") {
      output += renderNodes(isTruthy(resolve(node.path, context)) ? node.body : node.alternate, context);
    } else {
      const value = resolve(node.path, context);
      if (Array.isArray(value) && value.length > 0) {
        output += value.map((item, index) => renderNodes(node.body, { root: context.root, current: item, index })).join("");
      } else {
        output += renderNodes(node.alternate, context);
      }
    }
  }
  return output;
}

/** Render a Mini Template string using a root data value. */
export function render(template: string, data: unknown): string {
  return renderNodes(parse(template), { root: data, current: data });
}
import { render } from "./engine.ts";

const [templateFile, dataFile] = Bun.argv.slice(2);

if (!templateFile || !dataFile || Bun.argv.slice(2).length !== 2) {
  console.error("Usage: bun run src/cli.ts TEMPLATE_FILE DATA.json");
  process.exit(1);
}

try {
  const [template, json] = await Promise.all([
    Bun.file(templateFile).text(),
    Bun.file(dataFile).text(),
  ]);
  process.stdout.write(render(template, JSON.parse(json)));
} catch (error) {
  console.error(error instanceof Error ? error.message : String(error));
  process.exit(1);
}
import { describe, expect, test } from "bun:test";
import { render } from "../src/engine.ts";

describe("render", () => {
  test("interpolates and escapes scalar values", () => {
    expect(render("Hi {{user.name}}: {{value}}", { user: { name: "Ada" }, value: "<&>\"'" })).toBe("Hi Ada: &lt;&amp;&gt;&quot;&#39;");
    expect(render("{{{value}}}", { value: "<em>safe</em>" })).toBe("<em>safe</em>");
    expect(render("x{{missing}}y", {})).toBe("xy");
  });

  test("renders nested conditionals using specified truthiness", () => {
    expect(render("{{#if a}}A{{#if b}}B{{else}}C{{/if}}{{else}}D{{/if}}", { a: true, b: 0 })).toBe("AC");
    expect(render("{{#if value}}yes{{else}}no{{/if}}", { value: [] })).toBe("no");
  });

  test("iterates with this, index, root fallback, nesting, and else", () => {
    const template = "{{#each groups}}{{title}}:{{#each this}}[{{@index}}={{this}}/{{title}}]{{/each}};{{else}}empty{{/each}}";
    expect(render(template, { title: "root", groups: [["a", "b"], ["c"]] })).toBe("root:[0=a/root][1=b/root];root:[0=c/root];");
    expect(render("{{#each items}}x{{else}}none{{/each}}", { items: [] })).toBe("none");
  });

  test("removes comments and preserves surrounding whitespace", () => {
    expect(render(" a {{! invisible }}\n b ", {})).toBe(" a \n b ");
  });

  test("reports structural and non-scalar errors", () => {
    expect(() => render("{{#if a}}", {})).toThrow("Unclosed if block at line 1, column 1");
    expect(() => render("{{/each}}", {})).toThrow("line 1, column 1");
    expect(() => render("{{else}}", {})).toThrow("else outside a block");
    expect(() => render("{{item}}", { item: {} })).toThrow("Cannot render object as text");
  });
});
# Mini Template

A small, dependency-free TypeScript template renderer for Bun.

## Use as a library

```ts
import { render } from "./src/engine.ts";

render("Hello, {{user.name}}!", { user: { name: "Ada" } });
```

`{{path}}` HTML-escapes text; `{{{path}}}` leaves it unescaped. Supported blocks are `{{#if path}}…{{else}}…{{/if}}` and `{{#each path}}…{{else}}…{{/each}}`. In an `each`, use `{{this}}` and `{{@index}}`; ordinary paths resolve from the root data object.

## CLI

```sh
bun run src/cli.ts TEMPLATE_FILE DATA.json
```

It writes only the rendered result to stdout. Usage, file, JSON, and template errors are written to stderr with a non-zero exit status.

## Tests

```sh
bun test
